#!/usr/bin/env python3
"""Hand encoding of Sigal's report structure -> data/sigal_partition.json.
Theme -> report topic comes from the report's appendix tables; `moves` from the
comment log. Holds AI theme labels, topic names, ids and rater counts only."""
import json,os,sys
R=os.path.expanduser(sys.argv[1]); OUT=sys.argv[2]
# (theme label, report topic, raters, pro, con) : appendix tables of the report
A=[("שקט, שלווה ובנייה נמוכה","שקט, שלווה ובנייה נמוכה",80,79,0),
("פינות נוי, פריחה והצללה","חזות הישוב",66,64,0),("חיבור לטבע ומרחבים פתוחים","חזות הישוב",73,70,1),
("גינון, צמחייה והצללה","חזות הישוב",42,39,0),("ניקיון ונראות המרחב הציבורי","חזות הישוב",81,75,2),
("יחסי שכנות ושייכות קהילתית","לכידות קהילתית",86,82,2),("סיוע הדדי, התנדבות וחוסן","סיוע הדדי והתנדבות",89,82,4),
("אירועי חגים ומסורות מקומיות","תרבות קהילתית",76,70,1),("טקסים קהילתיים ולאומיים","תרבות קהילתית",58,53,1),
("מרחבי קהילה, תרבות ויוזמות","תרבות קהילתית",68,60,1),("ותיקים וקשרים בין־דוריים","ותיקים וקשרים בין-דוריים",64,52,5),
("ניהול אוכלוסיית חתולי הכפר","חתולי הכפר",38,27,3),("ניהול ותקשורת קהילתית","ניהול ותקשורת קהילתית",40,29,5),
("מורשת, היסטוריה ותיעוד מקומי","מורשת, היסטוריה ותיעוד מקומי",24,19,3),("צביון היישוב ובית הכנסת","צביון היישוב ובית הכנסת",30,21,5),
("דרכים, שבילים ותשתיות גינון","דרכים, שבילים ותשתיות",24,17,3)]
B=[("חיבור בין קבוצות ותושבים","בינוי קהילה",70,69,0),("שכנות טובה ותחושת שייכות","בינוי קהילה",44,41,0),("הקשבה והתחשבות בין תושבים","בינוי קהילה",46,44,1),
("חינוך ותרבות לחיזוק הקהילה","בינוי קהילה",14,13,0),("אירועים קהילתיים ורב־דוריים","בינוי קהילה",19,17,0),("התנדבות וסיוע הדדי בקהילה","בינוי קהילה",40,36,2),
("מעורבות וייצוג בקבלת החלטות","מעורבות וייצוג בקבלת החלטות",26,26,0),("מבנים ומסגרות לגיל הרך","מבנים ומסגרות לגיל הרך",40,36,2),
("גינון, השקיה וטיפוח הכפר","שיפור פני הכפר",29,26,0),("צל, עצים ושבילים","שיפור פני הכפר",52,47,2),
("אכיפה ויישום כללי הקבוצה","שיח ציבורי",1,1,0),("הידברות ויישוב מחלוקות","שיח ציבורי",10,9,0),("כללי התנהלות בקבוצות ווטסאפ","שיח ציבורי",21,20,0),
("נוער, צעירים ומנהיגות","נוער, צעירים ומנהיגות",56,51,1),("בחירת בעלי תפקידים ואחריותם","בחירת בעלי תפקידים ואחריותם",56,47,3),("נגישות למידע ופרוטוקולים","נגישות למידע ופרוטוקולים",23,21,1),
("מתקני ספורט ומשחק","מתקני ספורט ומשחק",53,44,4),("הסדרת המרחב הציבורי","הסדרת המרחב הציבורי",69,59,3),("פיתוח ההרחבה והמרחבים הקהילתיים","פיתוח ההרחבה והמרחבים הקהילתיים",53,46,4),
("ניקיון, אשפה ומיחזור","ניקיון, אשפה ומיחזור",37,33,1),("העשרה וחוגים לילדים","העשרה וחוגים לילדים",22,20,0),("עסקים, מסחר ותיירות מקומית","עסקים, מסחר ותיירות מקומית",50,39,3),
("מיסים, תקציב ואמצעי תשלום","מיסים, תקציב ואמצעי תשלום",37,31,3),("מרחבי מועדון ובילוי למבוגרים","מרחבי מועדון ובילוי למבוגרים",23,18,2),("טבע, מורשת ואיכות הסביבה","טבע ואיכות הסביבה",37,26,2),
("פעילויות פנאי ותוכן למבוגרים ומתבגרים","פעילויות פנאי ותוכן למבוגרים",19,16,3),("קבלה, הכלה וקליטת תושבים","קבלה וקליטת תושבים",25,18,4)]
# single-statement edits, by statement id
MOV={'IqKVla0ZHw-m':[("N2PV49RTKdAf62pa9Oym","חוסן קהילתי בשעת חירום","split"),("tbq1biWxUXQMpbgPDnIi","חוסן קהילתי בשעת חירום","split"),("vWeCaZBmEf10","חוסן קהילתי בשעת חירום","split"),
 ("8PFmyxpMFOGGVPbQ00wR","צביון היישוב ובית הכנסת","move#9"),("OJNB-dOWEbHY","שקט, שלווה ובנייה נמוכה","doubly-filed: report places it here"),("SGpNK3mwjXHGPSYUiqqU","חוסן קהילתי בשעת חירום","move#12"),("vtxVZgXqjH5dcamZoAy6","ניהול ותקשורת קהילתית","move#11")],
 'WfkDISMmbduQ':[("0P9O5EJW7cWF","מורשת ותיעוד","split"),("20ioHSvq3zAn0JbpYLzM","מורשת ותיעוד","split"),("p4fcUJuas4GTPJw5QSUc","מורשת ותיעוד","split"),("FAzi5CNp92ORlVgHlTAY",None,"removed#21"),("-6lrcO8PfcBq","בינוי קהילה","doubly-filed: report places it here"),("YKKdQeo0Epu4","בינוי קהילה","doubly-filed: report places it here")]}
out={}
for q,T in [('IqKVla0ZHw-m',A),('WfkDISMmbduQ',B)]:
    S=json.load(open(f"{R}/lineage-{q}.json"))['statements']; th={s['statement']:s for s in S if s.get('derivedByPipeline')=='topic-cluster' and not s.get('hide')}
    rows=[]
    assert len(T)==len(th),(len(T),len(th))
    for lab,topic,r,p,c in T:
        t=th[lab]; rows.append(dict(themeId=t['statementId'],label=lab,topic=topic,reportRaters=r,reportPro=p,reportCon=c))
    mv=[]
    for i,to,why in MOV[q]:
        mv.append(dict(atomId=i,toTopic=to,why=why))
    out[q]=dict(themes=rows,moves=mv)
# S2: residual request still open in the report (Q.A clusters 3+7, comment 25 / open question 4)
out['IqKVla0ZHw-m']['s2Merges']=[["לכידות קהילתית","סיוע הדדי והתנדבות","חוסן קהילתי בשעת חירום"]]
out['WfkDISMmbduQ']['s2Merges']=[]
json.dump(out,open(OUT,'w'),ensure_ascii=False,indent=1)
print({q:(len(v['themes']),len({t['topic'] for t in v['themes']}|{m['toTopic'] for m in v['moves'] if m['toTopic']})) for q,v in out.items()})
